window.STORY_CHAPTERS["c34988b705383c1fa"]={"id":"c34988b705383c1fa","lines":[{"uid":"talk.vc.home_season_kirito_4#originalText","id":"talk.vc.home_season_kirito_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"你知道吗？冬天是一整年中，最能清楚看见一等星的时候。要不要今晚一起去观星啊？","en":"Did you know you can see the stars the best in winter? Wanna go stargazing tonight?","ja":"知ってるか? 冬は一年で一番星がきれいに見えるんだぜ今夜一緒に、どうだ?"},"kind":"dialogue"},{"uid":"talk.vc.home_season_kirito_child_1#originalText","id":"talk.vc.home_season_kirito_child_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这个季节真不错呢，不冷也不热的。一直维持在春天不是很好吗。","en":"I love this time of year. Not too cold, not too hot... Why can't it be spring all the time?","ja":"この季節はいいよなあ寒くもなく、暑くもなくてずっと春ならいいのに"},"kind":"dialogue"},{"uid":"talk.vc.home_season_kirito_child_2#originalText","id":"talk.vc.home_season_kirito_child_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"在这种日子，食物的天命会迅速减少。得赶紧吃掉才行。","en":"The life of food depletes quickly on days like this. We'd better eat quickly before it goes bad.","ja":"こんな日は食べ物の天命がすぐ減っちゃうからな急いで食べないと"},"kind":"dialogue"},{"uid":"talk.vc.home_season_kirito_child_3#originalText","id":"talk.vc.home_season_kirito_child_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"啊～天气又变冷了。虽然说，我是也不讨厌冷空气啦……","en":"Aw, it's gotten cold again. I don't exactly hate the cold air, but...","ja":"あー、また寒くなってきたな冷たい空気も、嫌いじゃないんだけど……"},"kind":"dialogue"},{"uid":"talk.vc.home_season_kirito_child_4#originalText","id":"talk.vc.home_season_kirito_child_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"天气一冷，拿斧头的手就会痛呢……敲打的时候都会麻麻的。","en":"My hands sure hurt when I use the axe on cold days like this. When it hits the tree, my hands sting.","ja":"寒いと斧を持つ手が痛いよな……打ち付ける時、じーんとしてさ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_klein_1#originalText","id":"talk.vc.home_season_klein_1","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"春天的天气舒服归舒服……但就是让人想睡这点不好。","en":"I like how warm spring is... But it always makes me so sleepy.","ja":"春ってのは、気候はいいけど……どうも眠くていけねぇや"},"kind":"dialogue"},{"uid":"talk.vc.home_season_klein_2#originalText","id":"talk.vc.home_season_klein_2","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"是说也太热了吧？快来台空调啊。","en":"Man, it sure is hot. I wish we had air conditioning.","ja":"それにしても暑いなエアコンが欲しいぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_klein_3#originalText","id":"talk.vc.home_season_klein_3","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"偶尔在户外活动筋骨也不赖，常言道「运动之秋」嘛。","en":"Hey, how about we exercise outside today? I think people do sometimes say \"Autumn is for sports\"?","ja":"たまには外で体を動かすのも悪くないぜスポーツの秋っていうからな"},"kind":"dialogue"},{"uid":"talk.vc.home_season_klein_4#originalText","id":"talk.vc.home_season_klein_4","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"唔唔，好冷！这种天气窝在家里最棒了。","en":"Brrr, so cold! On days like this, it's best to just stay inside.","ja":"うう、さぶっ!こんな日は部屋にこもるのが一番だぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_kureha_1#originalText","id":"talk.vc.home_season_kureha_1","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"春天和许多人相会、离别……心情的浮动很激烈呢。","en":"Spring is the season for meeting people and breakups... It's a season that really stirs the heart.","ja":"春って、いろんな人と出会ったり、別れたり……気持ちがすごく揺れるよね"},"kind":"dialogue"},{"uid":"talk.vc.home_season_kureha_2#originalText","id":"talk.vc.home_season_kureha_2","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"好热喔－－这种日子就想去有河或湖的地方玩呢。","en":"It's pretty hot, ain't it. A day like this makes me want to go play in the river or lake.","ja":"暑いねーこんな日は、川とか湖のエリアで遊びたいなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_kureha_3#originalText","id":"talk.vc.home_season_kureha_3","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"看到已经转红的叶子，我就会有点开心。因为我是「红叶」啊。","en":"Looking at the leaves turn color makes me a little happy. It's because I'm a 'Kureha'.","ja":"紅葉している葉っぱを見ると、ちょっとうれしくなるの。ほら、あたし「クレハ」だから"},"kind":"dialogue"},{"uid":"talk.vc.home_season_kureha_4#originalText","id":"talk.vc.home_season_kureha_4","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"因为是冬天就一直窝在家里，这样可是会退步的！","en":"Winter means being confined to your house, like in a cage. My skills will get dull!","ja":"冬だからって、ずっと家に籠ってると腕が鈍っちゃうよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_season_leafa_1#originalText","id":"talk.vc.home_season_leafa_1","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"今天真是赏花的好日子呢！在花谢之前，大家一起去看吧。","en":"Today is a perfect day for a picnic under the blossoms! Let's all get there before all the petals fall!","ja":"今日はお花見日和だね! 散っちゃう前に、みんなで行こうよ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_leafa_2#originalText","id":"talk.vc.home_season_leafa_2","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"之前总觉得夏天让人忧郁，但如今我会游泳了，很开心！","en":"I used to hate summer, but now that I can swim, I love it!","ja":"前は夏が憂鬱だったけど今は泳げるから楽しいんだ! "},"kind":"dialogue"},{"uid":"talk.vc.home_season_leafa_3#originalText","id":"talk.vc.home_season_leafa_3","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"一到这个季节就会多愁善感。因为起始和回归，都是在秋天嘛。","en":"Whenever this season rolls around, I can't help but think that this was when you left and also when you came home.","ja":"この季節になると、考えちゃう始まったのも帰ってきたのも秋のことだったから"},"kind":"dialogue"},{"uid":"talk.vc.home_season_leafa_4#originalText","id":"talk.vc.home_season_leafa_4","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"冬天的道场好冷喔……特别是早上，冷到脚都要冻僵了。","en":"The dojo is always freezing in the winter. Especially in the morning. I feel like my toes will freeze off.","ja":"冬は、道場が寒いんだよね……特に朝は、足が凍りそうに冷たくなるんだよ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_linel_1#originalText","id":"talk.vc.home_season_linel_1","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"春天会开很多花吧？好想去外面看一看。","en":"Many flowers bloom during the spring, yes? I would love to go outside just once to see them.","ja":"春はたくさんの花が咲くんですよね?一度、外に見に行きたいです"},"kind":"dialogue"},{"uid":"talk.vc.home_season_linel_2#originalText","id":"talk.vc.home_season_linel_2","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"我流了一些汗，先去换个衣服喔。","en":"I've gotten a little sweaty. I'll just go change my clothes.","ja":"ちょっと汗をかいてしまいました着替えてきますね"},"kind":"dialogue"},{"uid":"talk.vc.home_season_linel_3#originalText","id":"talk.vc.home_season_linel_3","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"秋天的时候，教会的伙食也会稍微变好吃。我有点期待这点……","en":"In autumn, meals at the Church are a bit tastier. I look forward to that.","ja":"秋は教会のご飯も少しおいしくなるんですそれがちょっと楽しみです……"},"kind":"dialogue"},{"uid":"talk.vc.home_season_linel_4#originalText","id":"talk.vc.home_season_linel_4","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"天冷的时候，叫出热能素因就会稍微变暖和喔。","en":"When the weather is cold, summoning a thermal element helps keep you warm.","ja":"寒い時は、神聖術で熱素をを呼び出すと少し暖かいですよ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_lisbeth_1#originalText","id":"talk.vc.home_season_lisbeth_1","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"这个季节忽冷忽热的，很难选衣服穿耶。真羡慕男人。","en":"I hate how spring is warm one day, cold the next. It's a struggle to figure out which uniform to wear. Boys don't know how easy they have it.","ja":"この季節は、暖かかったり寒かったり、服装が難しいのよね男の人が羨ましい"},"kind":"dialogue"},{"uid":"talk.vc.home_season_lisbeth_2#originalText","id":"talk.vc.home_season_lisbeth_2","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"夏天就忍不住会想吃刨冰。冰比较绵密的那种。","en":"When summer rolls around, I always crave shaved ice, the fluffy kind!","ja":"夏になると、かき氷が食べたくなっちゃうふわふわの氷のやつ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_lisbeth_3#originalText","id":"talk.vc.home_season_lisbeth_3","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"秋天啊，会让人感到寂寞呢。……说笑的，那不像我嘛。","en":"Autumn always makes me feel kinda melancholy. Wow, eew. That sounded cheesy.","ja":"秋って、なんか寂しい気分になっちゃうのよね……なーんて、あたしらしくないか"},"kind":"dialogue"},{"uid":"talk.vc.home_season_lisbeth_4#originalText","id":"talk.vc.home_season_lisbeth_4","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"冬天就是要吃火锅！我跟西莉卡要办火锅派对，你也一起吃吧！","en":"Nothing says winter better than hot pot! Silica and I are having a hot pot party. You should come!","ja":"冬といえばお鍋! シリカと鍋パーティーやるから一緒に食べましょう! "},"kind":"dialogue"},{"uid":"talk.vc.home_season_medina_1#originalText","id":"talk.vc.home_season_medina_1","speaker":{"cn":"梅蒂娜","en":"Medina","ja":"メディナ"},"text":{"cn":"春天很常见到猫。小猫会不断成长，每天看着牠们会觉得很开心。","en":"I notice a lot of cats in the spring. Because that's when the kittens start to get bigger. It's something I enjoy looking at every day.","ja":"春は猫をよく見かける子猫はどんどん大きくなるから毎日見るのが楽しいんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_medina_2#originalText","id":"talk.vc.home_season_medina_2","speaker":{"cn":"梅蒂娜","en":"Medina","ja":"メディナ"},"text":{"cn":"使用冻素和风素就会变得凉快？你就只有在想这种事的时候最厉害。","en":"Will it get cooler with chill and wind elements? You must be at a high level to think of something like that!","ja":"凍素と風素で涼しくなる?お前は、こういう思いつきだけは一級品だな"},"kind":"dialogue"},{"uid":"talk.vc.home_season_medina_3#originalText","id":"talk.vc.home_season_medina_3","speaker":{"cn":"梅蒂娜","en":"Medina","ja":"メディナ"},"text":{"cn":"落叶会成为下一个季节花朵绽放的养分。我也想变成那样……","en":"The scattered leaves will help become nourishment for the flowers to bloom next season. I also want to be like that...","ja":"散りゆく葉も、次の季節に花を咲かせるための糧になる私も、そうなりたい……"},"kind":"dialogue"},{"uid":"talk.vc.home_season_medina_4#originalText","id":"talk.vc.home_season_medina_4","speaker":{"cn":"梅蒂娜","en":"Medina","ja":"メディナ"},"text":{"cn":"因为很冷所以不想出去？说这种软弱的话有什么用，快去外面吧。","en":"It's cold so don't you want to step outside? What are you going to do with something so cowardly? Hurry up and get to the front!","ja":"寒いから外に出たくない?そんな軟弱なことでどうするさっさと表に行くぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_nergius_integrator_1#originalText","id":"talk.vc.home_season_nergius_integrator_1","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"气温终于开始转暖了，这样人民的活动多少会更加热络吧。","en":"The weather has finally warmed up. The peasants will likely become more active now.","ja":"ようやく暖かくなってきた民たちの活動もこれで少しは活発になるでしょう"},"kind":"dialogue"},{"uid":"talk.vc.home_season_nergius_integrator_2#originalText","id":"talk.vc.home_season_nergius_integrator_2","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"天气热成这样，连汐抚都受不了呢……带牠去冲冲水好了。","en":"It is so hot that even Shionade is exhausted. Perhaps I should take them swimming.","ja":"こう暑くては、汐撫も参ってしまうな……水浴びに連れて行ってやろう"},"kind":"dialogue"},{"uid":"talk.vc.home_season_nergius_integrator_3#originalText","id":"talk.vc.home_season_nergius_integrator_3","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"索鲁斯下沉的时间越来越早，我想人民很快就会开始准备过冬。","en":"Solus is starting to set much earlier now. The peasants will likely begin the harvest soon.","ja":"ソルスが沈むのが早くなってきたまもなく、民たちが冬備えを始めると思います"},"kind":"dialogue"},{"uid":"talk.vc.home_season_nergius_integrator_4#originalText","id":"talk.vc.home_season_nergius_integrator_4","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"葱的时令确实是冬季，但请别说什么萌岚枪好像很好吃。","en":"Green onions are indeed ripe in the winter, but please, stop drooling over my hair.","ja":"確かにネギの旬は冬ですが萌嵐槍をうまそうだ、などと言うのはやめていただきたい"},"kind":"dialogue"},{"uid":"talk.vc.home_season_phillia_1#originalText","id":"talk.vc.home_season_phillia_1","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"看到春天的樱花，总觉得有点感伤。嘿嘿……是不是不像我会说的话？","en":"Looking at the cherry blossoms in the spring... Sure is a calm season. Ehehe...Doesn't suit me, don't you think?","ja":"春の桜を見ると、なんだかちょっとしんみりしちゃうんだえへへ……似合わないよね?"},"kind":"dialogue"},{"uid":"talk.vc.home_season_phillia_2#originalText","id":"talk.vc.home_season_phillia_2","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"在热的时候，就是要流一堆汗，再尽情地冲凉！","en":"This summer heat makes me sweat so much that I want to jump straight into the sea!","ja":"こういう暑いときはたっくさん汗をかいてその後思い切り水浴びしたい!"},"kind":"dialogue"},{"uid":"talk.vc.home_season_phillia_3#originalText","id":"talk.vc.home_season_phillia_3","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"我最喜欢秋天了！有很多好吃的东西！今天要吃什么好呢－－","en":"There are a lot of delicious food in the fall! I love it! I wonder what I should have today.","ja":"秋って、おいしい食べ物がたくさんあって大好き!今日は何を食べようかなー"},"kind":"dialogue"},{"uid":"talk.vc.home_season_phillia_4#originalText","id":"talk.vc.home_season_phillia_4","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"虽然我怕冷，但是喜欢雪。总觉得染上一片雪白的世界很美好。","en":"I don't do well with the cold, but I do like the snow. Somehow, the world covered in white is such a beautiful thing.","ja":"寒いのは苦手だけど、雪は好き世界が真っ白になるのはなんだかステキだよね"},"kind":"dialogue"},{"uid":"talk.vc.home_season_premiere_1#originalText","id":"talk.vc.home_season_premiere_1","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"春天是一年的序幕。我的名字：普蕾蜜亚也是一样的意思……总觉得有点开心。","en":"Spring signals the start of a new year. Same meaning as my name: Premiere... Somehow that makes me happy.","ja":"春は一年の幕開け私の名前、プレミアと同じ意味……なんとなく、うれしいです"},"kind":"dialogue"},{"uid":"talk.vc.home_season_premiere_2#originalText","id":"talk.vc.home_season_premiere_2","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"我听说天气热的时候，会换上比较单薄的衣服。我也跟着换上比较好吗？","en":"I heard that you wear less layers when it's hot. Should I also do the same?","ja":"暑いときは、薄着になると聞きます私も、そうした方がいいのでしょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_season_premiere_3#originalText","id":"talk.vc.home_season_premiere_3","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"在这个季节经常听到「当季」这个词呢。我听说那是在指好吃的东西。","en":"I hear 'seasonal' a lot during this tim. I thought it was some sort of delicious food when I first heard it.","ja":"この季節は「旬」という言葉をよく耳にしますとてもおいしいものだと聞きました"},"kind":"dialogue"},{"uid":"talk.vc.home_season_premiere_4#originalText","id":"talk.vc.home_season_premiere_4","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"雪明明只是水冰冻后的结晶，不过却会唤起人们的各种情感呢。真是不可思议……","en":"Even though snow is just frozen water crystals, it really makes me recall many emotions. I feel a little strange...","ja":"雪は水が凍った結晶なのにいろいろな感情を想起させますね不思議な感じがします……"},"kind":"dialogue"},{"uid":"talk.vc.home_season_rain_1#originalText","id":"talk.vc.home_season_rain_1","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"我有点喜欢春天的雨。唰唰－－的声音听起来很像温柔的歌声吧？","en":"I kind of like spring showers. Don't you think it's like listening to a gentle song?","ja":"春の雨って、ちょっと好きさーって優しく歌ってるみたいに聞こえるでしょ?"},"kind":"dialogue"},{"uid":"talk.vc.home_season_rain_2#originalText","id":"talk.vc.home_season_rain_2","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"虽然我想去海边，但是我不擅长运动……不游泳也可以吗？","en":"I want to go to the beach, but I'm not the sportive type... Would it be ok if I don't swim?","ja":"海には行きたいけど、わたし運動あまり得意じゃないし……泳がなくても、いい?"},"kind":"dialogue"},{"uid":"talk.vc.home_season_rain_3#originalText","id":"talk.vc.home_season_rain_3","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"在俄罗斯，这个季节已经呼出来的已经是白雾了。那边的寒冷，总觉得有点怀念。","en":"In Russia, we can see the our own breath in this temperature. Thinking of that cold makes me feel a little nostalgic.","ja":"ロシアだと、この季節にはもう息が白く見えるのあの寒さも、少し懐かしいな"},"kind":"dialogue"},{"uid":"talk.vc.home_season_rain_4#originalText","id":"talk.vc.home_season_rain_4","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"其实在冬天的某些日子，可以看到很大的彩虹喔。……总有一天，想要跟你一起去看。","en":"In the winter time, there are days where you can see a huge rainbow. ...Someday, I hope to go see it with you.","ja":"冬って、実は大きな虹が見える日があるんだよ……いつか、一緒に見たいね"},"kind":"dialogue"},{"uid":"talk.vc.home_season_ronye_1#originalText","id":"talk.vc.home_season_ronye_1","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"天气变温暖了，所以想再跟大家办亲睦会呢。","en":"Now that the weather is warm, I would love to have another picnic with our friends.","ja":"暖かくなってきたのでまたみんなで親睦会をやりたいですね"},"kind":"dialogue"},{"uid":"talk.vc.home_season_ronye_2#originalText","id":"talk.vc.home_season_ronye_2","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"学长，今天穿黑色的衣服不会热吗？","en":"Mentor, don't you find your black clothes a little too hot for today?","ja":"先輩、今日は黒い服は少し暑くないですか? "},"kind":"dialogue"},{"uid":"talk.vc.home_season_ronye_3#originalText","id":"talk.vc.home_season_ronye_3","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"飘落的枯叶，会成为下个新芽的养分，对吧……","en":"Even fallen leaves serve a purpose. They will feed next year's new leaves.","ja":"散ってしまった葉も次の新芽の栄養になるんですよね……"},"kind":"dialogue"},{"uid":"talk.vc.home_season_ronye_4#originalText","id":"talk.vc.home_season_ronye_4","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"冬天的天空好高……总有一天，我想飞上去看看。","en":"The winter sky is so high... I would love to fly up there someday.","ja":"冬は空が高くて……いつか、あそこを飛んでみたいです"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sachi_1#originalText","id":"talk.vc.home_season_sachi_1","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"好想再去看看开在春天的花朵呢。","en":"I'd love to have a picnic under the blossoms again sometime.","ja":"お花がたくさん咲いてるフィールドまた見に行きたいなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sachi_2#originalText","id":"talk.vc.home_season_sachi_2","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"今天好热啊～流了一身汗，全身黏答答的。","en":"It sure is hot today! I'm all sticky with sweat.","ja":"今日は暑いねー汗で体がベタベタするよ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sachi_3#originalText","id":"talk.vc.home_season_sachi_3","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"秋天的风很冷……我可以到你身边吗？","en":"Autumn's winds are so cold. So...can I come a bit closer?","ja":"秋風は冷たいから……ちょっと近くに行ってもいい?"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sachi_4#originalText","id":"talk.vc.home_season_sachi_4","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"冬天虽然冷，但我不讨厌。因为染上白色的世界很美丽。","en":"Winter is cold, but I don't mind. The world is beautiful when it's covered in white.","ja":"冬は寒いけど、嫌いじゃないんだ白く染まった世界は、キレイだから"},"kind":"dialogue"},{"uid":"talk.vc.home_season_selka_1#originalText","id":"talk.vc.home_season_selka_1","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"小牛会在春天出生，照顾牠们可辛苦了。","en":"Calves are born in the summer, so it's a busy season for me.","ja":"春は子牛が生まれるからそのお世話で大変なのよ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_selka_2#originalText","id":"talk.vc.home_season_selka_2","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"马上就要到夏至祭典了。呵呵，今年会有哪些摊位呢？","en":"It's almost time for the Solstice Festival. Hehe, I can't wait to see what booths they have this year.","ja":"もうすぐ夏至のお祭りねふふ、今年はどんなお店が出るのかしら"},"kind":"dialogue"},{"uid":"talk.vc.home_season_selka_3#originalText","id":"talk.vc.home_season_selka_3","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"天气变凉爽后，饭菜也终于比较耐放了。","en":"I'm glad the weather is cool enough now that food has a longer shelf life.","ja":"涼しくなって、やっとご飯が日持ちするようになってきたの"},"kind":"dialogue"},{"uid":"talk.vc.home_season_selka_4#originalText","id":"talk.vc.home_season_selka_4","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"虽然下雪时大家都很开心，但是会造成道路结冻等等，还是有很多麻烦事喔。","en":"Everyone else seems to love the snow, but with frozen roads, it has its own share of problems.","ja":"雪が降ると、みんな楽しそうだけど道が凍ったり、大変なことも多いのよ?"},"kind":"dialogue"},{"uid":"talk.vc.home_season_seven_1#originalText","id":"talk.vc.home_season_seven_1","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"春天的雨有种温柔的感觉。为什么呢？","en":"I wonder why spring showers feel so gentle.","ja":"春に降る雨って、なんか優しく感じるのどうしてかしらね"},"kind":"dialogue"},{"uid":"talk.vc.home_season_seven_2#originalText","id":"talk.vc.home_season_seven_2","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"好热喔－－热成这样脑袋也动不了……不管了，今天的工作到此为止！","en":"It's pretty hot, isn't it? I can't operate in this heat... Let's call it a day already!","ja":"暑いわねーこう暑いと、頭が働かないし……もう、今日はお仕事終了!"},"kind":"dialogue"},{"uid":"talk.vc.home_season_seven_3#originalText","id":"talk.vc.home_season_seven_3","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"日本的秋天有很多好吃的东西呢！今天要吃什么好呢－－","en":"I heard that there are a lot of delicious food in the fall in Japan! I wonder what I should eat today?","ja":"日本の秋は、おいしいものがたくさんあるわね!今日は何を食べようかしら?"},"kind":"dialogue"},{"uid":"talk.vc.home_season_seven_4#originalText","id":"talk.vc.home_season_seven_4","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"虽然寒冷让人难受，不过思考似乎会变清晰。所以，我喜欢冬天。","en":"The cold is a bitter thing, but I feel like it clears your mind. That's why, I like winter.","ja":"寒いのは辛いけど思考がクリアになる気がするのだから、冬は好きよ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_silica_1#originalText","id":"talk.vc.home_season_silica_1","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"春天有着各式各样的相遇跟离别……让我觉得自己也必须成长才行。","en":"Spring is filled with all sorts of hellos and goodbyes. It makes me feel so young, like I have to grow up.","ja":"春は、いろんな出会いとか別れがあって……あたしも成長しなきゃって思います"},"kind":"dialogue"},{"uid":"talk.vc.home_season_silica_2#originalText","id":"talk.vc.home_season_silica_2","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"哇，好大的西瓜喔。我拿不动……","en":"Wow! Now that's a big watermelon. I can't even lift it.","ja":"わあ、大きなスイカですねお、重くて、持ってられません……"},"kind":"dialogue"},{"uid":"talk.vc.home_season_silica_3#originalText","id":"talk.vc.home_season_silica_3","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"秋天的水果很美味，我跟莉兹姊姊她们常常会一起去吃。","en":"The fruit is so tasty in the fall, that me and Liz will go out to eat some.","ja":"秋は果物がおいしくてリズさんたちと一緒によく食べに行きます"},"kind":"dialogue"},{"uid":"talk.vc.home_season_silica_4#originalText","id":"talk.vc.home_season_silica_4","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"呜呜，暖桌太温暖了，完全没办法出去……","en":"Oh, man...this blanket is so warm, I can't get out from under it.","ja":"うう、こたつが暖かすぎてなかなか出られません……"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sinon_1#originalText","id":"talk.vc.home_season_sinon_1","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"看到别人恍神的样子，就会连自己都跟着想睡呢。是春天的缘故吗……","en":"Seeing you looking so sleepy is making me sleepy, too. Is it the spring air, I wonder?","ja":"眠そうな様子を見てるとこっちまで眠くなってくるわ春だから、かしら……"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sinon_2#originalText","id":"talk.vc.home_season_sinon_2","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"连续好几天都是大热天，就会想逃到虚拟世界呢……","en":"When each day is hot like this, I feel like retreating into the virtual world.","ja":"こんなに暑い日が続くと仮想世界に逃げたくなるわね……"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sinon_3#originalText","id":"talk.vc.home_season_sinon_3","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"你该不会没带外套吧？明明今天会变冷耶……来，这个给你，可别感冒了。","en":"Do you not have a coat? It's supposed to be chilly today. Here, take this. I don't want you catching cold.","ja":"もしかして上着がないの? 今日は寒くなるのに……はい、これ。風邪引かないように"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sinon_4#originalText","id":"talk.vc.home_season_sinon_4","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"天气一冷我就会想起那事件……但我已经不要紧了。因为有你在我身边啊。","en":"Cold days remind me of the incident... But I'm over it now. You keep me present.","ja":"寒くなると、事件を思い出すけど……もう大丈夫だって、あなたがいてくれるから"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sortiliena_1#originalText","id":"talk.vc.home_season_sortiliena_1","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"每到春天，就会想起和你相遇的光景。我认为自己一辈子都不会忘记。","en":"Whenever spring rolls around, I remember meeting you for the first time. I don't think I'll ever forget it.","ja":"春になると、お前との出会いを思い出すよ一生忘れられないと思う"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sortiliena_2#originalText","id":"talk.vc.home_season_sortiliena_2","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"呼，流了一身汗。……协助更衣可不是随侍的工作喔。","en":"Phew, I worked up quite a sweat. Helping me change clothes... is not in a page's job description. Got it?","ja":"ふう、汗をかいてしまったな……着替えの手伝いは側付きの仕事ではないぞ? "},"kind":"dialogue"},{"uid":"talk.vc.home_season_sortiliena_3#originalText","id":"talk.vc.home_season_sortiliena_3","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"剑斩落叶啊……这尝试听起来很有趣呢。","en":"We attempt to slice falling leaves with our swords? Amusing. I like this challenge.","ja":"落ち葉を剣で切る、か……面白そうだな、その試みは"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sortiliena_4#originalText","id":"talk.vc.home_season_sortiliena_4","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"在冷空气中训练，就会感到身心紧绷。","en":"Whenever I train in the cold like this, I feel both my heart and mind tighten up.","ja":"冷たい空気の中で稽古をすると身も心も引き締まる気がする"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sortiliena_child_1#originalText","id":"talk.vc.home_season_sortiliena_child_1","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"时间过得真快……已经春天了啊。","en":"Time really does fly! I blinked and spring had already arrived.","ja":"時がすぎるのは早い……もう春になってしまった"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sortiliena_child_2#originalText","id":"talk.vc.home_season_sortiliena_child_2","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"大热天进行训练，实在是会忍不住去在意汗水……","en":"Training on hot days does make me self-conscious about my sweat.","ja":"暑い日の稽古はさすがにちょっと汗が気になってしまう……"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sortiliena_child_3#originalText","id":"talk.vc.home_season_sortiliena_child_3","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"如同能斩断落叶的犀利剑击……","en":"Slash a falling leaf? Easy! All I need is a sharp sword...","ja":"落ちる枯れ葉を切れるくらい鋭い剣撃を……"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sortiliena_child_4#originalText","id":"talk.vc.home_season_sortiliena_child_4","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"天气一冷，跷掉练习的人就会多，所以对我来说反而是好机会！","en":"Many people skip practice on cold days, which means it's just an opportunity for me to get in extra training!","ja":"寒いと稽古を怠ける人が多いから私にとっては逆に良い機会なんだ!"},"kind":"dialogue"},{"uid":"talk.vc.home_season_strea_1#originalText","id":"talk.vc.home_season_strea_1","speaker":{"cn":"斯朵蕾雅","en":"Strea","ja":"ストレア"},"text":{"cn":"变暖和了呢－－下次和大家一起去赏花嘛！一定会很开心的！","en":"It's gotten warm outside. Let's go view the cherry blossoms with everyone next time! That will be fun, for sure.","ja":"暖かくなってきたねー今度さ、みんなでお花見しようよ!きっと楽しいよー"},"kind":"dialogue"},{"uid":"talk.vc.home_season_strea_2#originalText","id":"talk.vc.home_season_strea_2","speaker":{"cn":"斯朵蕾雅","en":"Strea","ja":"ストレア"},"text":{"cn":"说到夏天就是大海！穿上泳装，大家一起去做海水浴吧！","en":"Summer means going to the beach! Let's all put on some swimsuits and head to the sea!","ja":"夏といえば海!水着着て、みんなで海水浴に行こう!"},"kind":"dialogue"},{"uid":"talk.vc.home_season_strea_3#originalText","id":"talk.vc.home_season_strea_3","speaker":{"cn":"斯朵蕾雅","en":"Strea","ja":"ストレア"},"text":{"cn":"看到从树上落下的叶子，为什么会感到有点寂寞呢。","en":"Looking at the leaves fall off the trees is a little sad, don't you think?","ja":"木から落ちる葉っぱを見るとなんでちょっと寂しくなるんだろうね"},"kind":"dialogue"},{"uid":"talk.vc.home_season_strea_4#originalText","id":"talk.vc.home_season_strea_4","speaker":{"cn":"斯朵蕾雅","en":"Strea","ja":"ストレア"},"text":{"cn":"呜呜……今天好冷喔－－呐，可以靠紧你一下下吗？","en":"Uhh... Today is pretty cold. Hey, could we get just a little closer?","ja":"うう……今日は寒いねーね、ちょっとだけくっついてもいい?"},"kind":"dialogue"},{"uid":"talk.vc.home_season_suguha_1#originalText","id":"talk.vc.home_season_suguha_1","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"今天真是赏花的好日子呢！在花谢之前，大家一起去看吧。","en":"Today is a perfect day for a picnic under the blossoms! Let's all get there before all the petals fall!","ja":"今日はお花見日和だね! 散っちゃう前に、みんなで行こうよ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_suguha_2#originalText","id":"talk.vc.home_season_suguha_2","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"之前总觉得夏天让人忧郁，但如今我会游泳了，很开心！","en":"I used to hate summer, but now that I can swim, I love it!","ja":"前は夏が憂鬱だったけど今は泳げるから楽しいんだ! "},"kind":"dialogue"},{"uid":"talk.vc.home_season_suguha_3#originalText","id":"talk.vc.home_season_suguha_3","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"一到这个季节就会多愁善感。因为起始和回归，都是在秋天嘛。","en":"Whenever this season rolls around, I can't help but think that this was when you left and also when you came home.","ja":"この季節になると、考えちゃう始まったのも帰ってきたのも秋のことだったから"},"kind":"dialogue"},{"uid":"talk.vc.home_season_suguha_4#originalText","id":"talk.vc.home_season_suguha_4","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"冬天的道场好冷喔……特别是早上，冷到脚都要冻僵了。","en":"The dojo is always freezing in the winter. Especially in the morning. I feel like my toes will freeze off.","ja":"冬は、道場が寒いんだよね……特に朝は、足が凍りそうに冷たくなるんだよ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_tiese_1#originalText","id":"talk.vc.home_season_tiese_1","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"每到这个季节，我就会想起第一次见到学长的那天。","en":"Whenever this season rolls around, I'm reminded of the day we first met.","ja":"この季節になると先輩に初めてお会いした日を思い出します"},"kind":"dialogue"},{"uid":"talk.vc.home_season_tiese_2#originalText","id":"talk.vc.home_season_tiese_2","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"今天索鲁斯大人的光芒太强，我都快昏倒了……","en":"Solus' rays are so harsh today. I feel as though I'm going to faint.","ja":"今日はソルスの光が強すぎて倒れてしまいそうです……"},"kind":"dialogue"},{"uid":"talk.vc.home_season_tiese_3#originalText","id":"talk.vc.home_season_tiese_3","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"看着叶子落尽的树，我就会感到有些惆怅。","en":"Whenever I see the naked trees, I feel a little lonely.","ja":"葉がなくなってしまった木を見ると、少し寂しくなってしまいます"},"kind":"dialogue"},{"uid":"talk.vc.home_season_tiese_4#originalText","id":"talk.vc.home_season_tiese_4","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"今天很冷呢。您摸摸看，手都变那么冰了……","en":"What a cold day! Just feel how icy my hands are.","ja":"今日は寒いですねほら、手がこんなに冷たくて……"},"kind":"dialogue"},{"uid":"talk.vc.home_season_tiese_child_1#originalText","id":"talk.vc.home_season_tiese_child_1","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"积雪终于都溶化了。就这样天气能变暖和就好了。","en":"Finally, the snow is gone! It would be great if this meant that it gets warmer.","ja":"やっと雪が溶けましたねこれで暖かくなるといいなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_tiese_child_2#originalText","id":"talk.vc.home_season_tiese_child_2","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"这么热的天气，就连挥剑也觉得辛苦啊……","en":"Swinging a sword in this heat is tough...","ja":"こんなに暑いと、剣を振るのも大変なんです……"},"kind":"dialogue"},{"uid":"talk.vc.home_season_tiese_child_3#originalText","id":"talk.vc.home_season_tiese_child_3","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"看到落叶，总觉得有点寂寞……","en":"Looking at the leaves fall off the trees is so sad...","ja":"葉っぱが散るのを見ているとなんだか寂しくなるな……"},"kind":"dialogue"},{"uid":"talk.vc.home_season_tiese_child_4#originalText","id":"talk.vc.home_season_tiese_child_4","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"下雪虽然会很麻烦，但心情就会不由得雀跃起来。","en":"Things get harder when it starts snowing, but I can't help but get a little excited.","ja":"雪が降ると大変だけどなんだかわくわくしてしまうんです"},"kind":"dialogue"},{"uid":"talk.vc.home_season_yui_1#originalText","id":"talk.vc.home_season_yui_1","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"等樱花开了，我们就一起去赏花吧！妈妈会帮我们做便当的！","en":"Let's go see the cherry blossoms when they bloom! Mom will make us a picnic.","ja":"桜が咲いたらお花見に行きましょう!ママがお弁当を作ってくれますよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_season_yui_2#originalText","id":"talk.vc.home_season_yui_2","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"夏天就是要去海水浴场呢。不知道Alicization的世界里有没有大海……","en":"Summer is indeed the season for beaches. Does the Alicization world have oceans?","ja":"夏といえば海水浴ですねアンダーワールドには海はないのでしょうか……"},"kind":"dialogue"},{"uid":"talk.vc.home_season_yui_3#originalText","id":"talk.vc.home_season_yui_3","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"天气渐渐变冷了，衣服要穿暖一点再出门喔。","en":"The weather is getting cold, so bundle up when you go out, okay?","ja":"だんだん寒くなってきましたから暖かい格好で出かけてくださいね"},"kind":"dialogue"},{"uid":"talk.vc.home_season_yuna_1#originalText","id":"talk.vc.home_season_yuna_1","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"春天会开很多花呢。看起来是不是很像大家在唱歌的样子啊？","en":"A lot of flowers blossom in the spring, huh. Doesn't it seem like everyone is singing?","ja":"春は、お花がたくさん咲くよねなんか、みんな歌ってるみたいに見えない?"},"kind":"dialogue"},{"uid":"talk.vc.home_season_yuna_2#originalText","id":"talk.vc.home_season_yuna_2","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"今天好热喔－－千万不要太专心玩游戏，玩到忘记补充水分喔！","en":"Today's a scorcher, isn't it. Try not to get too caught up in the game and stay hydrated.","ja":"今日は暑いねーゲームに夢中になって、水分補給を怠らないようにね!"},"kind":"dialogue"},{"uid":"talk.vc.home_season_yuna_3#originalText","id":"talk.vc.home_season_yuna_3","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"一到秋天，我就会想读书呢。这就是所谓的\"读书之秋\"吗！？","en":"For some reason when it's the fall, I want to read books. I guess it's called 'fall reading'!?","ja":"秋になると、なんだか本を読みたくなるの\"読書の秋\"っていうやつかな!?"},"kind":"dialogue"},{"uid":"talk.vc.home_season_yuna_4#originalText","id":"talk.vc.home_season_yuna_4","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"我喜欢雪，因为和我的头发颜色一样。虽然一直下雪的话也会很困扰。","en":"Since snow is the same color as my hair, I like winter. It's a little bit troublesome if it snows a lot, but...","ja":"雪って、私の髪と同じ色をしてるから、私好きなんだたくさん降ると、困っちゃうけど"},"kind":"dialogue"},{"uid":"talk.vc.home_season_yuuki_1#originalText","id":"talk.vc.home_season_yuuki_1","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"看到春天时努力冒出的新芽，就会觉得莫名开心。","en":"Whenever I see fresh, new buds on the trees in spring, I just feel warm and fuzzy inside.","ja":"春、新しい芽が頑張って出てくる姿を見るとなんだかうれしくなるんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_yuuki_2#originalText","id":"talk.vc.home_season_yuuki_2","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"木棉花会在夏天绽放。所以，我也超喜欢夏天！","en":"I love summer because that's when the cotton flowers bloom!","ja":"木綿の花は夏に咲くんだだから、ボクも夏が大好き! "},"kind":"dialogue"},{"uid":"talk.vc.home_season_yuuki_3#originalText","id":"talk.vc.home_season_yuuki_3","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"秋天啊，光是在家里听到风的咻咻声，就会觉得很冷对吧。","en":"You know how in autumn, the wind kinda goes \"wooo\" through the house? Just hearing that makes me shiver.","ja":"秋はさ、家の中でびょおおって風の音を聞くだけで、なんだか寒くなってくるよね"},"kind":"dialogue"},{"uid":"talk.vc.home_season_yuuki_4#originalText","id":"talk.vc.home_season_yuuki_4","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"这么寒冷的日子里，就会想跟某人窝在一起。","en":"On cold days like this, I always feel like being around people.","ja":"こんな寒い日は、誰かと一緒にいたいんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_administrator_1#originalText","id":"talk.vc.home_time_administrator_1","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"我还需要休息，你懂吧？","en":"I need to sleep still. You understand, don't you?","ja":"私はまだ休む必要があるのわかるでしょう?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_administrator_2#originalText","id":"talk.vc.home_time_administrator_2","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"来，起床了。……希望有顺利「调整」好。","en":"Come. Wake up. I hope the...adjustments...I made worked out well.","ja":"さあ、起きなさい……うまく「調整」できているといいのだけど"},"kind":"dialogue"},{"uid":"talk.vc.home_time_administrator_4#originalText","id":"talk.vc.home_time_administrator_4","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"如非必要，就别来叫我起床。","en":"Don't wake me unless it’s truly important.","ja":"必要がなければ私のことを起こさないように"},"kind":"dialogue"},{"uid":"talk.vc.home_time_administrator_5#originalText","id":"talk.vc.home_time_administrator_5","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"似乎有高违反系数的人呢。呵呵……会是怎样的孩子呢？","en":"My, my. Isn’t someone rebellious? Hehe... just what kind of boy are you?","ja":"違反係数が高いユニットがあるみたいねふふ……どんな子なのかしら?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_administrator_7#originalText","id":"talk.vc.home_time_administrator_7","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"很久没像今天这样保持清醒，真是累死我了。","en":"Being awake today after a long sleep was very tiring.","ja":"今日は久しぶりに起きて疲れてしまったわ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_administrator_8#originalText","id":"talk.vc.home_time_administrator_8","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"这么晚了，有什么事吗？","en":"What do you want at this ungodly hour?","ja":"こんな時間に、何の用?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_administrator_10#originalText","id":"talk.vc.home_time_administrator_10","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"居然趁着晚上偷偷跑来，真是个坏孩子。我是不是应该要惩罚你呢。","en":"You bad boy, barging in on me at night. Somebody needs to be disciplined.","ja":"夜に忍んでくるなんて、悪い子ね?お仕置きが必要かしら"},"kind":"dialogue"},{"uid":"talk.vc.home_time_administrator_11#originalText","id":"talk.vc.home_time_administrator_11","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"这个世界是我的……不论面对外面的世界，还是暗之子民，我都绝对不会交出去。","en":"This world is mine. I won't surrender it to anyone. Neither to the outside world nor the forces of Darkness.","ja":"この世界は私のもの……外の世界にも、闇の輩にも決して渡したりはしないわ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_administrator_uw_sleeping_3#originalText","id":"talk.vc.home_time_administrator_uw_sleeping_3","speaker":{"ja":"アドミニストレータ"},"text":{"ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_time_administrator_uw_sleeping_6#originalText","id":"talk.vc.home_time_administrator_uw_sleeping_6","speaker":{"ja":"アドミニストレータ"},"text":{"ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_time_administrator_uw_sleeping_9#originalText","id":"talk.vc.home_time_administrator_uw_sleeping_9","speaker":{"ja":"アドミニストレータ"},"text":{"ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_time_agil_1#originalText","id":"talk.vc.home_time_agil_1","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"我不擅长早起。因为一开起店，就必然会晚睡嘛。","en":"I don't like mornings. Running this bar, I have to stay up late by necessity.","ja":"オレ、朝は得意じゃないんだ店をやってると、必然的に寝るのが遅くなるからな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_agil_2#originalText","id":"talk.vc.home_time_agil_2","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"想睡觉的话就去冲个澡吧，头脑会变清醒喔。","en":"The best cure for sleepiness is a shower. It really clears the head.","ja":"眠かったらシャワーを浴びるんだな頭がスッキリするぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_agil_4#originalText","id":"talk.vc.home_time_agil_4","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"午餐，就来我这吃吧。","en":"Have lunch at my place.","ja":"昼飯なら、ウチで食べていけよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_agil_5#originalText","id":"talk.vc.home_time_agil_5","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"我这里有试作的菜色，要不要试一下味道？","en":"I've got some new menu items. Wanna taste them for me?","ja":"試作のメニューがあるんだちょっと味見してみないか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_agil_7#originalText","id":"talk.vc.home_time_agil_7","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"接下来才是我这间店的热门时段。","en":"This is the time of day when my job really gets busy.","ja":"オレの商売はこの時間からが本番だ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_agil_8#originalText","id":"talk.vc.home_time_agil_8","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"走夜路的时候要小心啊。","en":"Be careful when you're out walking at night.","ja":"夜道は気をつけろよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_agil_10#originalText","id":"talk.vc.home_time_agil_10","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"我差不多要关店了。你也去休息吧。","en":"Well, it's about time to close shop. You should call it a night, too.","ja":"さて、そろそろ店を閉めるぞお前も休んだらどうだ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_agil_11#originalText","id":"talk.vc.home_time_agil_11","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"你这个时候才睡，明天早上会很痛苦的。","en":"If you go to bed this late, you'll be a tired wreck tomorrow.","ja":"この時間に寝たんじゃ明日の朝はキツそうだな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_airy_1#originalText","id":"talk.vc.home_time_airy_1","speaker":{"cn":"升降员","en":"Operator","ja":"昇降係"},"text":{"cn":"早安。","en":"Good morning.","ja":"おはようございます"},"kind":"dialogue"},{"uid":"talk.vc.home_time_airy_4#originalText","id":"talk.vc.home_time_airy_4","speaker":{"cn":"升降员","en":"Operator","ja":"昇降係"},"text":{"cn":"差不多要中午了呢，请您要好好休息。","en":"It is almost time for lunch. Make sure you have your rest.","ja":"そろそろお昼の時間ですね休憩はしっかり取ってください"},"kind":"dialogue"},{"uid":"talk.vc.home_time_airy_7#originalText","id":"talk.vc.home_time_airy_7","speaker":{"cn":"升降员","en":"Operator","ja":"昇降係"},"text":{"cn":"差不多该休息了呢，请您不要太勉强自己。","en":"It is almost time for bed. Please, don't stay up too late.","ja":"そろそろお休みの時間ですねあまりご無理をされませんよう"},"kind":"dialogue"},{"uid":"talk.vc.home_time_airy_10#originalText","id":"talk.vc.home_time_airy_10","speaker":{"cn":"升降员","en":"Operator","ja":"昇降係"},"text":{"cn":"您也是来吹夜风的吗？","en":"Did you also come out here for a little night air?","ja":"あなたも、夜の風にあたりにきたのですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_airy_coverall_1#originalText","id":"talk.vc.home_time_airy_coverall_1","speaker":{"cn":"艾莉","en":"Airy","ja":"エアリー"},"text":{"cn":"早安。","en":"Good morning.","ja":"おはようございます"},"kind":"dialogue"},{"uid":"talk.vc.home_time_airy_coverall_4#originalText","id":"talk.vc.home_time_airy_coverall_4","speaker":{"cn":"艾莉","en":"Airy","ja":"エアリー"},"text":{"cn":"差不多要中午了呢，请您要好好休息。","en":"It is almost time for lunch. Make sure you have your rest.","ja":"そろそろお昼の時間ですね休憩はしっかり取ってください"},"kind":"dialogue"},{"uid":"talk.vc.home_time_airy_coverall_7#originalText","id":"talk.vc.home_time_airy_coverall_7","speaker":{"cn":"艾莉","en":"Airy","ja":"エアリー"},"text":{"cn":"差不多该休息了呢，请您不要太勉强自己。","en":"It is almost time for bed. Please, don't stay up too late.","ja":"そろそろお休みの時間ですねあまりご無理をされませんよう"},"kind":"dialogue"},{"uid":"talk.vc.home_time_airy_coverall_10#originalText","id":"talk.vc.home_time_airy_coverall_10","speaker":{"cn":"艾莉","en":"Airy","ja":"エアリー"},"text":{"cn":"您也是来吹夜风的吗？","en":"Did you also come out here for a little night air?","ja":"あなたも、夜の風にあたりにきたのですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_1#originalText","id":"talk.vc.home_time_alice_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"早安。真是舒爽的早晨呢，精力也随之充沛。","en":"Good morning. What a lovely morning it is. And I'm full of energy.","ja":"おはようございます気持ちのいい朝ですね気力も充実しています"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_2#originalText","id":"talk.vc.home_time_alice_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你还不快点起床？怠惰可是罪过。","en":"Why don't you get out of bed already? Sloth is one of the deadly sins.","ja":"いい加減に起きたらどうですか怠惰は罪です"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_3#originalText","id":"talk.vc.home_time_alice_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"早餐很重要。如果稍后还有劳务，就更不在话下了。","en":"Breakfast is very important. Especially if you have hard work to do.","ja":"朝食は重要ですこれから働くのであればなおさらですよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_4#originalText","id":"talk.vc.home_time_alice_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我今天打算帮《雨缘》洗澡，因为天气温暖又舒服啊。","en":"I was going to wash Amayori today. The warmth feels so soothing.","ja":"今日は《雨縁》の体を洗ってあげようと思うのです暖かくて気持ちがいいですから"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_5#originalText","id":"talk.vc.home_time_alice_5","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"真令人傻眼……才中午的就要睡吗？真亏你能睡得这么多。","en":"You never cease to frustrate me. How can you sleep in the middle of the day?","ja":"呆れた……昼から寝ているのですか? よくそれだけ睡眠が取れますね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_6#originalText","id":"talk.vc.home_time_alice_6","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"今天真是风和日丽，就让这把剑尽情沐浴阳光吧。","en":"Since the sun is so bright today, I will let my sword bathe in her abundant light.","ja":"今日はいい日和ですからこの剣にたっぷりと陽の光を浴びせてあげましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_7#originalText","id":"talk.vc.home_time_alice_7","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"今天也辛苦你了。晚上就不要勉强自己，好好休息吧。","en":"Good work today. Make sure you rest up well tonight.","ja":"今日もお疲れさまでした夜は無理せず、ゆっくりと休みましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_8#originalText","id":"talk.vc.home_time_alice_8","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"总觉得蔷薇的香味会在夜晚更加浓郁。是我多心了吗？","en":"Roses seem even more fragrant at night. Though, perhaps it's just my imagination.","ja":"夜は、薔薇の香りがいっそう強くなる気がするのです気のせいでしょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_9#originalText","id":"talk.vc.home_time_alice_9","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"在一日的尾声和你一起度过，常常让我感到不可思议。","en":"Sometimes I realize how surreal it is to spend an entire day with you like this.","ja":"1日の終わりに、お前と一緒に過ごしているのが、ときどき不思議に思えてきます"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_10#originalText","id":"talk.vc.home_time_alice_10","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"睡不着吗？这是因为你白天睡太久了。","en":"You can't sleep? Serves you right for napping during the day.","ja":"眠れないのですか? 昼間寝すぎるからですよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_11#originalText","id":"talk.vc.home_time_alice_11","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"……我作了一个梦。虽然不记得内容，但是个温暖又让人怀念的梦……","en":"I was dreaming. I don't remember much about it, but it was a warm dream about days past...","ja":"……夢を見ていました覚えていないけれど、とても暖かくて懐かしい夢を……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_12#originalText","id":"talk.vc.home_time_alice_12","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我去吹吹夜风。……你要一起来吗？","en":"I'm going out for a little night air. Would you...care to join me?","ja":"少し夜気に当たってきます……お前も一緒に来ますか? "},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_child_1#originalText","id":"talk.vc.home_time_alice_child_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"好了啦，起床了！太阳都晒屁股了。","en":"Wake up, wake up, wake up! It's already morning.","ja":"ほらほら、起きなさーい! もう朝なんだから"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_child_2#originalText","id":"talk.vc.home_time_alice_child_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"已经决定好今天要做什么了吗？","en":"Any plans today?","ja":"今日の予定は決まってるの? "},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_child_4#originalText","id":"talk.vc.home_time_alice_child_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我拿午餐过来啰。……我想，应该是蛮好吃的啦。","en":"Here, I've brought your lunch. It's delicious...I hope.","ja":"はい、お昼を持ってきたわ……おいしいと、思うんだけど"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_child_5#originalText","id":"talk.vc.home_time_alice_child_5","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我们以前会一起去摘花呢……真让人怀念。","en":"We used to pick flowers a lot when we were little... I really miss it.","ja":"昔は一緒にお花を摘んだりしたわよね……なんだか懐かしいわ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_child_7#originalText","id":"talk.vc.home_time_alice_child_7","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"这么晚了你还在工作吗？今天也辛苦你了。","en":"Wow, were you really up this late working? You're a trooper.","ja":"こんなに遅くまで働いてたの? 今日もお疲れさま"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_child_8#originalText","id":"talk.vc.home_time_alice_child_8","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"欸，你今天过得怎么样？可以说给我听吗？","en":"So, how was your day? Wanna talk about it?","ja":"ねえ、今日はどんな日だった? 私に教えてくれない? "},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_child_10#originalText","id":"talk.vc.home_time_alice_child_10","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"到了这么晚还没睡，会有些紧张呢。","en":"Being up this late at night is kind of exciting, huh?","ja":"夜こうやって起きてると少しドキドキしちゃうわね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_child_11#originalText","id":"talk.vc.home_time_alice_child_11","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"太晚了啦，快睡觉吧？这是为了让明天也是愉快的一天喔。","en":"We really should get some sleep now. I don't want to ruin tomorrow's fun.","ja":"さすがにもう寝ましょう明日を楽しい日にするために、ね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_uw_sleeping_3#originalText","id":"talk.vc.home_time_alice_uw_sleeping_3","speaker":{"ja":"アリス"},"text":{"ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_uw_sleeping_6#originalText","id":"talk.vc.home_time_alice_uw_sleeping_6","speaker":{"ja":"アリス"},"text":{"ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_uw_sleeping_9#originalText","id":"talk.vc.home_time_alice_uw_sleeping_9","speaker":{"ja":"アリス"},"text":{"ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alicia_1#originalText","id":"talk.vc.home_time_alicia_1","speaker":{"cn":"亚丽莎","en":"Alicia","ja":"アリシャ"},"text":{"cn":"早安喔～！我今天也很有精神喔！","en":"Good! Morniiing! What a great day!","ja":"おっはよー!今日もアタシは元気だヨ!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alicia_4#originalText","id":"talk.vc.home_time_alicia_4","speaker":{"cn":"亚丽莎","en":"Alicia","ja":"アリシャ"},"text":{"cn":"呼啊……我想睡觉了。来睡午觉吧？","en":"Mmm, I'm getting sleepy. Think I'll take a cat nap.","ja":"ふわあ……眠くなってきたヨお昼寝しようか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alicia_7#originalText","id":"talk.vc.home_time_alicia_7","speaker":{"cn":"亚丽莎","en":"Alicia","ja":"アリシャ"},"text":{"cn":"差不多该上床了吧？都已经这个时间了。","en":"Wanna go to bed? It's gotten pretty late.","ja":"そろそろベッドに行く?もうこんな時間だもんネ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alicia_10#originalText","id":"talk.vc.home_time_alicia_10","speaker":{"cn":"亚丽莎","en":"Alicia","ja":"アリシャ"},"text":{"cn":"呵呵，在大半夜像这样见面，会有种坏坏的感觉，很开心呢。","en":"Hehe, seeing you at night like this feels kinda naughty. I like it.","ja":"んふふ、夜中にこうやって会うのはなんかちょっとイケナイ感じで楽しいネ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_argo_1#originalText","id":"talk.vc.home_time_argo_1","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"情报商人都很早起的。","en":"No rest for the informant.","ja":"情報屋の朝は早いんだヨ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_argo_2#originalText","id":"talk.vc.home_time_argo_2","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"嗨，早安～有好康的，你买不买啊？","en":"Hey. 'Morning. Here to buy some juicy gossip?","ja":"よう、オハヨーおいしいネタ、買っていくカ?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_argo_4#originalText","id":"talk.vc.home_time_argo_4","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"情报必须要靠亲自走访来收集。放心吧，我一个人去。","en":"Info gathering takes a lot of leg work. Nah, it's cool. I can go by myself.","ja":"情報は足で稼がないトナ大丈夫、ひとりで行くカラ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_argo_5#originalText","id":"talk.vc.home_time_argo_5","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"毫无防备地睡午觉……还真悠闲啊。","en":"Look at you, napping out in the open... That's ballsy.","ja":"無防備に昼寝して……のんきなもんダナ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_argo_7#originalText","id":"talk.vc.home_time_argo_7","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"因为盯上我的人也很多，晚上必须要提高警戒才行。","en":"Lots of people are after me, so I have to be on my guard at night.","ja":"オレっちを狙うやつも多いカラ夜は警戒しないとナ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_argo_8#originalText","id":"talk.vc.home_time_argo_8","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"晚上大家的口风都会变松，对情报商人来说，是最佳时机呢。","en":"Nights always bring out everyone's secrets. That's what an informant like me aims for.","ja":"夜ってのは、みんな口が軽くなるんダ。情報屋にとっては狙い目なのサ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_argo_10#originalText","id":"talk.vc.home_time_argo_10","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"居然大半夜的跑来……你这么在意姊姊吗？","en":"Why'd you come to me so late at night? Were you worried about me?","ja":"こんな夜中に来るなんて……オネーサンのことが気になるのカナ?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_argo_11#originalText","id":"talk.vc.home_time_argo_11","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"你问我什么时候睡觉？要是被看到睡觉的样子，就不配当情报商人了喔。","en":"You wanna know when I find time to sleep? If I told you my secret, some informant I'd be.","ja":"いつ寝てるのかッテ?それを見られたら、情報屋失格ダヨ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_1#originalText","id":"talk.vc.home_time_asuna_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"早安。呵呵，我刚刚……仔细欣赏了你的睡脸。","en":"Good morning. Hehe...I watched you sleep.","ja":"おはようふふ、寝顔……じっくり見ちゃった"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_2#originalText","id":"talk.vc.home_time_asuna_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"男孩子早上三两下就可以梳洗好，真是羡慕。","en":"Boys are lucky. It takes them no time to get ready in the morning.","ja":"男の子は、朝の準備が簡単でいいなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_3#originalText","id":"talk.vc.home_time_asuna_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"你要好好吃早餐喔。就算不吃，都已经有点太瘦了。","en":"Breakfast is the most important meal of the day. You're too thin, regardless.","ja":"朝ごはんはしっかり食べてよねそれじゃなくても、少し痩せてるんだから"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_4#originalText","id":"talk.vc.home_time_asuna_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天天气真好。我们去外面吃饭吧？","en":"The weather sure is lovely today. Let's eat lunch outside.","ja":"今日はいいお天気ね外でご飯食べようか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_5#originalText","id":"talk.vc.home_time_asuna_5","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"你肚子饿了吗？我带了自己做的便当来，想找你一起吃。","en":"Are you hungry? I brought us a picnic lunch. Wanna share?","ja":"お腹すいてる?わたし、お弁当作ってきたの一緒にどうかなって"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_6#originalText","id":"talk.vc.home_time_asuna_6","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天的日照很强呢，好刺眼啊。","en":"The sun sure is bright today. It's kind of hard to see.","ja":"今日はちょっと日差しが強いねなんだか眩しい"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_7#originalText","id":"talk.vc.home_time_asuna_7","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天也辛苦你了。晚餐已经做好啰。","en":"Good work today! Dinner's ready.","ja":"今日もご苦労様でしたご飯できてるわよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_8#originalText","id":"talk.vc.home_time_asuna_8","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"平常都没发现，原来真正的夜晚这么黑啊。","en":"I usually don't notice it, but look at how dark night actually is!","ja":"普段は気が付かないけど本当の夜ってこんなに暗いんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_9#originalText","id":"talk.vc.home_time_asuna_9","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"偶尔在月光下散步，感觉也不错呢。","en":"Walking in the moonlight sure feels nice.","ja":"月明かりの下をお散歩するのもたまには気持ちがいいね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_10#originalText","id":"talk.vc.home_time_asuna_10","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"总觉得夜晚的空气很静谧呢。","en":"The night sky has a tranquil feel to it.","ja":"夜の空気って、なんか静謐な感じがするよね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_11#originalText","id":"talk.vc.home_time_asuna_11","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天有点睡不着……你可以陪我一下吗？","en":"I'm having a hard time sleeping tonight... Can I stay up with you a bit longer?","ja":"今日は、なんだか眠れなくて……少しだけ、一緒にいてもいい? "},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_12#originalText","id":"talk.vc.home_time_asuna_12","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"已经这么晚啦。不赶紧睡觉的话，明天会很难熬喔。","en":"Look how late it is. We'd better go to sleep or we'll be zombies tomorrow.","ja":"もうこんな時間ねそろそろ寝ないと、明日が大変だわ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_azurica_1#originalText","id":"talk.vc.home_time_azurica_1","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"早安。起床的时间到了喔。","en":"Good morning. It's time to get up.","ja":"おはようございますもう起床の時間ですよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_azurica_4#originalText","id":"talk.vc.home_time_azurica_4","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"用餐要细嚼慢咽，吃快了会对身体有害。","en":"Take your time when you eat. Eating too quickly causes indigestion.","ja":"食事は落ち着いてするように急いで食べると体に毒です"},"kind":"dialogue"},{"uid":"talk.vc.home_time_azurica_7#originalText","id":"talk.vc.home_time_azurica_7","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"快到门禁时间了喔，今天就打住吧。","en":"It's almost curfew. Let's wrap things up for the day.","ja":"門限の刻限が迫っていますよ今日はもう終わりになさい"},"kind":"dialogue"},{"uid":"talk.vc.home_time_azurica_10#originalText","id":"talk.vc.home_time_azurica_10","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"你还没睡吗……没办法，我去帮你弄点东西喝吧。","en":"You aren't asleep yet? Well, it can't be helped. Shall I bring you something to drink?","ja":"まだ寝ていないのですか……仕方ありませんなにか飲むものでも出しましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_time_bercouli_1#originalText","id":"talk.vc.home_time_bercouli_1","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"为什么早上总是让人这么想睡啊？","en":"I'm always sleepy in the morning.","ja":"朝ってのは、どうしてこうも眠いのかねぇ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_bercouli_2#originalText","id":"talk.vc.home_time_bercouli_2","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"喔，有早餐啊？抱歉每次都麻烦你，谢啦。","en":"Ooh, you got me breakfast? Thanks. You're always so helpful.","ja":"お、朝飯かいつもすまんな、ありがとう"},"kind":"dialogue"},{"uid":"talk.vc.home_time_bercouli_4#originalText","id":"talk.vc.home_time_bercouli_4","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"那么……天气这么好，我就跟星咬去飞一飞吧。你要一起来吗？","en":"Well, then. Since the weather is nice, I think I'll go for a dragon ride. Would you like to come along?","ja":"さて……天気もいいし星咬とひとっ飛びしてくるかなお前さんも来るか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_bercouli_5#originalText","id":"talk.vc.home_time_bercouli_5","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"哎唷，管他什么修练的。要是这么好的日子还训练，可是会遭天打雷劈啊。","en":"Oh, forget about training for one day. If you train on a day like this, the gods will punish you.","ja":"いいだろう、修練なんてこんな日に稽古なんかしたらバチが当たるぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_bercouli_7#originalText","id":"talk.vc.home_time_bercouli_7","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"好啦，洗澡啰洗澡啰。吃饭前就是要泡个澡啊。","en":"Okay. Time for a bath! I always love a bath before dinner.","ja":"さあて、風呂だ風呂飯の前にひとっ風呂浴びようぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_bercouli_8#originalText","id":"talk.vc.home_time_bercouli_8","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"晚上还去练剑啊？热衷练习是好，但还是休息一下吧。","en":"You spend your nights training, too? I admire your dedication, but try to get some sleep.","ja":"夜も剣の修練か?熱心なのはいいが、少しは休めよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_bercouli_10#originalText","id":"talk.vc.home_time_bercouli_10","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"你睡不着吗？那要不要喝点睡前酒？","en":"You can't sleep? Wanna have a nightcap?","ja":"眠れねえのか?だったら寝酒でもやるか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_bercouli_11#originalText","id":"talk.vc.home_time_bercouli_11","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"暂时也没任务在身，明天我要悠哉地睡他一觉。","en":"Since there's no missions lined up, I'll be able to sleep in tomorrow morning.","ja":"しばらくは任務もないし明日はゆっくり寝るぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_cardinal_1#originalText","id":"talk.vc.home_time_cardinal_1","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"已经早上啦……我太过沉浸在观察外部了。","en":"Morning already, eh? I must have gotten quite absorbed in observing the outside world.","ja":"もう朝か……外の観察にすっかり夢中になってしまった"},"kind":"dialogue"},{"uid":"talk.vc.home_time_cardinal_2#originalText","id":"talk.vc.home_time_cardinal_2","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"喂，起床了。你应该睡够了吧。","en":"Come, wake up. You should already be well rested.","ja":"ほれ、起きろもう充分に睡眠は取ったであろうが"},"kind":"dialogue"},{"uid":"talk.vc.home_time_cardinal_4#originalText","id":"talk.vc.home_time_cardinal_4","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"想吃饭？好啦，我是会帮你做……真是不懂得客气的家伙。","en":"You want breakfast? Well, I suppose I could prepare something... You have no shame, do you.","ja":"食事か?まあ、作ってやるが……遠慮を知らんヤツじゃな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_cardinal_5#originalText","id":"talk.vc.home_time_cardinal_5","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"索鲁斯之光啊……我已经好几年没有沐浴其中了呢。","en":"Solus' rays... It has been years since I've felt them.","ja":"ソルスの光か……もう何年も浴びてはおらんな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_cardinal_7#originalText","id":"talk.vc.home_time_cardinal_7","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"晚上要多加小心。那家伙的虫子会窸窸窣窣地四处打转。","en":"You must be careful at night. Their insects are buzzing.","ja":"夜は気をつけねばなあやつのムシがゴソゴソと嗅ぎ回っておる"},"kind":"dialogue"},{"uid":"talk.vc.home_time_cardinal_8#originalText","id":"talk.vc.home_time_cardinal_8","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"澡堂在对面，小心别感冒了。","en":"There's a bath down the hall. Be sure to dry off well.","ja":"風呂なら向こうにあるぞ風邪をひかんようにな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_cardinal_10#originalText","id":"talk.vc.home_time_cardinal_10","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"我的身体不需要睡眠，所以你就不用替我操心了。","en":"My body does not need sleep. So your thoughtfulness is wasted.","ja":"わしは睡眠が必要ない体なのじゃだから気遣いは無用じゃよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_cardinal_11#originalText","id":"talk.vc.home_time_cardinal_11","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"透过观察者眼睛看到的月亮，果然总是显得有些小，颜色也淡。","en":"Whenever I view the moon through another's eyes, it looks small and faded.","ja":"観察者の目を通して見る月はやはりどこか小さく色あせておるよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_dakira_1#originalText","id":"talk.vc.home_time_dakira_1","speaker":{"cn":"达基拉","en":"Dakira","ja":"ダキラ"},"text":{"cn":"早安！今天也请您多多指教！","en":"Good morning! I’m looking forward to working together today.","ja":"おはようございます!今日もよろしくお願いいたします!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_dakira_4#originalText","id":"talk.vc.home_time_dakira_4","speaker":{"cn":"达基拉","en":"Dakira","ja":"ダキラ"},"text":{"cn":"餐点就由我来准备吧。","en":"If you're hungry, would you like me to fetch you a meal?","ja":"食事でしたら私がご用意いたしましょう"},"kind":"dialogue"}]};
